use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;
use unicode_normalization::UnicodeNormalization;

/// Domain allowlist validator for Kubernetes job worker
/// Validates that webhook callback URLs point to approved internal services
#[derive(Clone)]
pub struct DomainValidator {
    allowed_domains: Arc<RwLock<HashMap<String, ServiceConfig>>>,
}

#[derive(Clone, Debug)]
pub struct ServiceConfig {
    pub name: String,
    pub namespace: String,
    pub max_retries: u32,
}

#[derive(Debug, Clone)]
pub struct JobRequest {
    pub job_id: String,
    pub callback_url: String,
    pub payload: Vec<u8>,
}

impl DomainValidator {
    pub fn new() -> Self {
        let mut domains = HashMap::new();
        domains.insert(
            "api.internal.cluster.local".to_string(),
            ServiceConfig {
                name: "api-service".to_string(),
                namespace: "production".to_string(),
                max_retries: 3,
            },
        );
        domains.insert(
            "webhook.internal.cluster.local".to_string(),
            ServiceConfig {
                name: "webhook-service".to_string(),
                namespace: "production".to_string(),
                max_retries: 5,
            },
        );
        domains.insert(
            "notifications.internal.cluster.local".to_string(),
            ServiceConfig {
                name: "notification-service".to_string(),
                namespace: "production".to_string(),
                max_retries: 2,
            },
        );
        DomainValidator {
            allowed_domains: Arc::new(RwLock::new(domains)),
        }
    }

    /// Normalize domain with full Unicode NFKC normalization and ASCII validation
    /// This prevents homograph attacks by rejecting non-ASCII domains
    fn normalize_domain(&self, domain: &str) -> Result<String, ValidationError> {
        // Apply NFKC normalization to decompose compatibility characters
        let nfkc: String = domain.nfkc().collect();
        // Apply case folding
        let lowered = nfkc.to_lowercase();
        // Strip any trailing dots (FQDN format)
        let stripped = lowered.trim_end_matches('.');
        // CRITICAL: Reject any domain containing non-ASCII characters
        // This prevents Unicode homograph attacks entirely
        if !stripped.is_ascii() {
            return Err(ValidationError::NonAsciiDomain(stripped.to_string()));
        }
        // Additional check: only allow alphanumeric, hyphens, and dots
        if !stripped.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '.') {
            return Err(ValidationError::InvalidDomainChars(stripped.to_string()));
        }
        Ok(stripped.to_string())
    }

    /// Validates that the callback URL's domain is in our allowlist
    pub async fn validate_callback_url(&self, url: &str) -> Result<ServiceConfig, ValidationError> {
        // Reject URLs with non-ASCII characters before parsing
        if !url.is_ascii() {
            return Err(ValidationError::NonAsciiDomain(url.to_string()));
        }

        let parsed = url::Url::parse(url).map_err(|_| ValidationError::InvalidUrl)?;

        let scheme = parsed.scheme();
        if scheme != "https" && scheme != "http" {
            return Err(ValidationError::InvalidScheme);
        }

        let host = parsed
            .host_str()
            .ok_or(ValidationError::MissingHost)?;

        let normalized = self.normalize_domain(host)?;

        let domains = self.allowed_domains.read().await;
        domains
            .get(&normalized)
            .cloned()
            .ok_or(ValidationError::DomainNotAllowed(normalized))
    }
}

#[derive(Debug)]
pub enum ValidationError {
    InvalidUrl,
    InvalidScheme,
    MissingHost,
    DomainNotAllowed(String),
    NonAsciiDomain(String),
    InvalidDomainChars(String),
}

pub struct JobWorker {
    validator: DomainValidator,
    http_client: reqwest::Client,
}

impl JobWorker {
    pub fn new() -> Self {
        JobWorker {
            validator: DomainValidator::new(),
            http_client: reqwest::Client::builder()
                .timeout(std::time::Duration::from_secs(30))
                .build()
                .unwrap(),
        }
    }

    /// Process a job and send results to the callback URL
    pub async fn process_job(&self, request: JobRequest) -> Result<(), Box<dyn std::error::Error>> {
        // Validate the callback URL domain
        let service_config = self
            .validator
            .validate_callback_url(&request.callback_url)
            .await
            .map_err(|e| format!("Validation failed: {:?}", e))?;

        log::info!(
            "Processing job {} for service {} in namespace {}",
            request.job_id,
            service_config.name,
            service_config.namespace
        );

        // Simulate job processing
        let result = self.execute_job_logic(&request.payload).await?;

        // Send callback with retry logic
        let mut attempts = 0;
        loop {
            attempts += 1;
            match self
                .http_client
                .post(&request.callback_url)
                .header("X-Job-Id", &request.job_id)
                .header("X-Worker-Node", std::env::var("NODE_NAME").unwrap_or_default())
                .body(result.clone())
                .send()
                .await
            {
                Ok(resp) if resp.status().is_success() => {
                    log::info!("Job {} callback delivered successfully", request.job_id);
                    return Ok(());
                }
                Ok(resp) => {
                    log::warn!("Job {} callback returned {}", request.job_id, resp.status());
                }
                Err(e) => {
                    log::error!("Job {} callback failed: {}", request.job_id, e);
                }
            }

            if attempts >= service_config.max_retries {
                return Err(format!(
                    "Job {} callback failed after {} attempts",
                    request.job_id, attempts
                )
                .into());
            }

            tokio::time::sleep(std::time::Duration::from_millis(500 * attempts as u64)).await;
        }
    }

    async fn execute_job_logic(&self, payload: &[u8]) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
        // Simulate computation
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        Ok(payload.to_vec())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_valid_domain() {
        let validator = DomainValidator::new();
        let result = validator
            .validate_callback_url("https://api.internal.cluster.local/callback")
            .await;
        assert!(result.is_ok());
    }

    #[tokio::test]
    async fn test_invalid_domain() {
        let validator = DomainValidator::new();
        let result = validator
            .validate_callback_url("https://evil.example.com/callback")
            .await;
        assert!(result.is_err());
    }

    #[tokio::test]
    async fn test_normalized_domain() {
        let validator = DomainValidator::new();
        // FQDN with trailing dot should still match
        let result = validator
            .validate_callback_url("https://api.internal.cluster.local./callback")
            .await;
        assert!(result.is_ok());
    }

    #[tokio::test]
    async fn test_homograph_rejected() {
        let validator = DomainValidator::new();
        // Cyrillic 'а' in 'api' should be rejected
        let result = validator
            .validate_callback_url("https://\u{0430}pi.internal.cluster.local/callback")
            .await;
        assert!(result.is_err());
    }
}
